namespace sv_3a7e9ee78d9b460c9e0361c3a86a1f04.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_3a7e9ee78d9b460c9e0361c3a86a1f04.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1 class="mb-4">Product Catalog</h1>

@if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}
else
{
    <div class="d-flex">
        <!-- Sidebar Filters -->
        <div class="pe-4" style="width: 25%; min-width: 220px;">
            <div class="card">
                <div class="card-header fw-bold">Filters</div>
                <div class="card-body">
                    <!-- Category checkboxes -->
                    <h6>Category</h6>
                    @if (categories is null)
                    {
                        <p class="text-muted small">Loading categories…</p>
                    }
                    else
                    {
                        @foreach (var category in categories)
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                                       checked="@selectedCategories.Contains(category)"
                                       @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                                <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                            </div>
                        }
                    }

                    <hr />

                    <!-- Price range -->
                    <h6>Price Range</h6>
                    <div class="mb-2">
                        <label class="form-label small mb-0">Min Price</label>
                        <input type="number" class="form-control form-control-sm" min="0" step="0.01"
                               @bind="minPrice" placeholder="0.00" />
                    </div>
                    <div class="mb-2">
                        <label class="form-label small mb-0">Max Price</label>
                        <input type="number" class="form-control form-control-sm" min="0" step="0.01"
                               @bind="maxPrice" placeholder="No limit" />
                    </div>

                    <hr />

                    <!-- In stock only -->
                    <div class="form-check mb-3">
                        <input class="form-check-input" type="checkbox" id="inStockOnly"
                               @bind="inStockOnly" />
                        <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                    </div>

                    <!-- Buttons -->
                    <div class="d-grid gap-2">
                        <button class="btn btn-primary btn-sm" @onclick="ApplyFiltersAsync" disabled="@isLoading">
                            Apply Filters
                        </button>
                        <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFiltersAsync" disabled="@isLoading">
                            Clear Filters
                        </button>
                    </div>
                </div>
            </div>
        </div>

        <!-- Main Content -->
        <div style="width: 75%;">
            <!-- Toolbar -->
            <div class="d-flex justify-content-between align-items-center mb-3">
                <div class="d-flex align-items-center gap-2">
                    <label class="form-label mb-0 fw-semibold">Sort by:</label>
                    <select class="form-select form-select-sm" style="width: auto;" @onchange="OnSortChangedAsync">
                        @foreach (var option in sortOptions)
                        {
                            <option value="@option.Value" selected="@(sortBy == option.Value)">@option.Label</option>
                        }
                    </select>
                </div>
                <span class="text-muted small">
                    @if (result is not null && result.TotalCount > 0)
                    {
                        var start = (result.Page - 1) * result.PageSize + 1;
                        var end = Math.Min(result.Page * result.PageSize, result.TotalCount);
                        @($"Showing {start}–{end} of {result.TotalCount} products")
                    }
                </span>
            </div>

            <!-- Content States -->
            @if (isLoading)
            {
                <div class="text-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                    <p class="mt-2 text-muted">Loading products…</p>
                </div>
            }
            else if (result is null || result.Items.Count == 0)
            {
                <div class="text-center py-5">
                    <p class="text-muted fs-5">No products found matching your criteria.</p>
                    <button class="btn btn-outline-primary" @onclick="ClearFiltersAsync">Clear Filters</button>
                </div>
            }
            else
            {
                <!-- Product Grid -->
                <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-3">
                    @foreach (var product in result.Items)
                    {
                        <div class="col">
                            <ProductCard Product="product" OnProductSelected="OnProductSelected" />
                        </div>
                    }
                </div>

                <!-- Pagination -->
                @if (totalPages > 1)
                {
                    <nav class="mt-4" aria-label="Product pagination">
                        <ul class="pagination justify-content-center">
                            <li class="page-item @(currentPage == 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(currentPage - 1)"
                                        disabled="@(currentPage == 1)">Previous</button>
                            </li>
                            @foreach (var p in GetPageNumbers())
                            {
                                <li class="page-item @(p == currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="() => GoToPageAsync(p)">@p</button>
                                </li>
                            }
                            <li class="page-item @(currentPage == totalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(currentPage + 1)"
                                        disabled="@(currentPage == totalPages)">Next</button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        </div>
    </div>
}

@code {
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? categories;
    private PagedResult<Product>? result;

    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 9;

    private bool isLoading = true;
    private string? errorMessage;

    private int totalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / result.PageSize);

    private static readonly (string Label, string Value)[] sortOptions =
    [
        ("Price: Low to High", "price_asc"),
        ("Price: High to Low", "price_desc"),
        ("Name: A-Z", "name_asc"),
        ("Rating: Highest", "rating_desc")
    ];

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        try
        {
            isLoading = true;
            errorMessage = null;

            var categoriesTask = categories is null
                ? ProductService.GetCategoriesAsync()
                : Task.FromResult(categories);
            var searchTask = ProductService.SearchAsync(BuildFilter(), sortBy, currentPage, PageSize);

            await Task.WhenAll(categoriesTask, searchTask);

            categories = await categoriesTask;
            result = await searchTask;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private ProductFilter BuildFilter() => new(
        Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
        MinPrice: minPrice,
        MaxPrice: maxPrice,
        InStockOnly: inStockOnly
    );

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFiltersAsync()
    {
        currentPage = 1;
        await LoadDataAsync();
    }

    private async Task ClearFiltersAsync()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        sortBy = "price_asc";
        currentPage = 1;
        await LoadDataAsync();
    }

    private async Task OnSortChangedAsync(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await LoadDataAsync();
    }

    private async Task GoToPageAsync(int page)
    {
        if (page < 1 || page > totalPages) return;
        currentPage = page;
        await LoadDataAsync();
    }

    private async Task RetryAsync()
    {
        await LoadDataAsync();
    }

    private IEnumerable<int> GetPageNumbers()
    {
        const int maxVisible = 5;
        int start = Math.Max(1, currentPage - maxVisible / 2);
        int end = Math.Min(totalPages, start + maxVisible - 1);
        start = Math.Max(1, end - maxVisible + 1);

        for (int i = start; i <= end; i++)
            yield return i;
    }
}

@using sv_3a7e9ee78d9b460c9e0361c3a86a1f04.Services

<div class="card h-100 product-card" @onclick="HandleCardClick" role="button" style="cursor: pointer;">
    <!-- Placeholder image -->
    <div class="card-img-top bg-light d-flex align-items-center justify-content-center"
         style="height: 180px;" role="img" aria-label="@Product.Name">
        <span class="text-muted">@Product.Name</span>
    </div>
    <div class="card-body d-flex flex-column">
        <h6 class="card-title mb-1">@Product.Name</h6>
        <p class="fw-bold text-primary mb-1">@Product.Price.ToString("C")</p>
        <p class="mb-2">
            <span class="text-warning">@GetStarRating(Product.Rating)</span>
            <span class="text-muted small ms-1">(@Product.Rating.ToString("0.0"))</span>
        </p>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2">Out of Stock</span>
        }
        <div class="mt-auto">
            <button class="btn btn-sm btn-success w-100"
                    disabled="@(!Product.InStock)"
                    @onclick="HandleAddToCart"
                    @onclick:stopPropagation="true">
                Add to Cart
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Product Product { get; set; } = default!;
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }

    private static string GetStarRating(double rating)
    {
        int filled = (int)Math.Round(rating);
        return new string('★', filled) + new string('☆', 5 - filled);
    }

    private async Task HandleCardClick()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private void HandleAddToCart()
    {
        // Add to cart logic would go here
    }
}

